if(!obterTokenCliente())location.href='login.html';(async()=>{try{const c=await apiFetch('/auth/clientes/me');document.getElementById('conta-nome').textContent='Olá, '+c.nome;const ps=await apiFetch('/pedidos/meus');const u=ps[0];document.getElementById('ultima-encomenda').innerHTML=u?`<span>#${u.numeroPedido} · ${estadoPT(u.estado)}</span><span>${Number(u.totalEUR||0).toLocaleString('pt-PT',{style:'currency',currency:'EUR'})}</span>`:'<span>Ainda não existem encomendas.</span><span></span>';}catch(e){console.error(e)}})();
